// @/components/Header.tsx
import React from "react";
import Image from "next/image";
import { KURUMSAL } from "@/lib/dictionaryConstants";

interface HeaderProps {
  karanlikMod: boolean;
  toggleKaranlikMod: () => void;
  metinBoyutu: number;
  setMetinBoyutu: React.Dispatch<React.SetStateAction<number>>;
  tema: any; // İleride daha katı bir interface tanımlayabiliriz
}

export default function Header({ 
  karanlikMod, 
  toggleKaranlikMod, 
  metinBoyutu, 
  setMetinBoyutu,
  tema 
}: HeaderProps) {
  
  return (
    <header style={{ 
      display: "flex", 
      justifyContent: "space-between", 
      alignItems: "center", 
      marginBottom: "16px", 
      flexWrap: "wrap", 
      gap: "12px", 
      borderBottom: `2px solid ${KURUMSAL.sari}`, 
      paddingBottom: "14px" 
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
        <Image 
          src="/logo.png" // Doğru logo yolunuzu buraya ekleyin
          alt="Açık Mektep Logosu" 
          width={42} 
          height={42} 
          style={{ objectFit: "contain", borderRadius: "8px" }} 
        />
        <div>
          <span style={{ 
            fontSize: `${metinBoyutu * 0.75}px`, 
            fontWeight: "bold", 
            color: KURUMSAL.kirmizi, 
            textTransform: "uppercase", 
            letterSpacing: "0.08em", 
            display: "block" 
          }}>
            Açık Mektep
          </span>
          <h1 style={{ 
            color: tema.yaziAna, 
            margin: 0, 
            fontSize: `${metinBoyutu * 1.5}px` 
          }}>
            📖 Çerkesçe Sözlük
          </h1>
        </div>
      </div>
      
      <div style={{ display: "flex", gap: "8px", alignItems: "center" }} role="toolbar" aria-label="Görünüm kontrolleri">
        <button 
          onClick={() => setMetinBoyutu((p) => Math.max(14, p - 2))} 
          aria-label="Yazı boyutunu küçült" 
          style={{ padding: "8px 12px", borderRadius: "6px", border: `1px solid ${tema.kenarlik}`, backgroundColor: tema.kartArkaPlan, color: tema.yaziAna, cursor: "pointer", fontWeight: "bold" }}>
          A-
        </button>
        <button 
          onClick={() => setMetinBoyutu((p) => Math.min(24, p + 2))} 
          aria-label="Yazı boyutunu büyüt" 
          style={{ padding: "8px 12px", borderRadius: "6px", border: `1px solid ${tema.kenarlik}`, backgroundColor: tema.kartArkaPlan, color: tema.yaziAna, cursor: "pointer", fontWeight: "bold" }}>
          A+
        </button>
        <button 
          onClick={toggleKaranlikMod} 
          aria-pressed={karanlikMod} 
          aria-label="Karanlık Temayı Aç/Kapat" 
          style={{ padding: "8px 14px", borderRadius: "6px", border: `1px solid ${tema.kenarlik}`, backgroundColor: tema.kartArkaPlan, color: tema.yaziAna, cursor: "pointer" }}>
          {karanlikMod ? "☀️ Aydınlık" : "🌙 Karanlık"}
        </button>
      </div>
    </header>
  );
}