"use client";

import React, { useState, useMemo, useEffect, useCallback } from "react";
import { useDictionary } from "@/hooks/useDictionary";
import Header from "@/components/Header";
import SearchBox from "@/components/SearchBox";
import GununKelimesiKarti from "@/components/GununKelimesiKart";
import SozlukEkrani from "@/components/SozlukEkrani";
import { AramaModu,GruplanmisKelime } from "@src\types\dictionary.ts";
import { types } from "util";
const LIMIT = 20;

export default function Home() {
  // 1. Hook'lardan gelen veriler
  const {
    wordsCount, loading, searchQuery, setSearchQuery,
    seciliLehce, setSeciliLehce, seciliDosya, setSeciliDosya,
    gununKelimesi, filtrelenmisSonuclar, aktifSozlukler,
  } = useDictionary();

  // 2. Sayfa içi UI State'leri
  const [mod, setMod] = useState<AramaModu>("baslayan");
  const [hedefDil, setHedefDil] = useState<string>("tumu");
  const [goruntulenenAdet, setGoruntulenenAdet] = useState<number>(LIMIT);
  const [karanlikMod, setKaranlikMod] = useState<boolean>(false);
  const [metinBoyutu, setMetinBoyutu] = useState<number>(16);
  const [seciliKelimeGrubu, setSeciliKelimeGrubu] = useState<GruplanmisKelime | null>(null);

  // Tema hesaplaması ve diğer logic fonksiyonları (gruplanmisSonuclar vb.) burada kalmaya devam edebilir 
  // veya custom hook'lara taşınabilir.
  
  if (loading) {
    return <div>📖 Sözlük veritabanı yükleniyor...</div>; // İleride LoadingSkeleton.tsx ile değişecek
  }

  return (
    <div className={`min-h-screen p-6 transition-colors ${karanlikMod ? "bg-[#0c0f17]" : "bg-slate-50"}`}>
      <main className="max-w-4xl mx-auto">
        
        <Header 
          karanlikMod={karanlikMod} 
          toggleKaranlikMod={() => setKaranlikMod(!karanlikMod)}
          metinBoyutu={metinBoyutu}
          setMetinBoyutu={setMetinBoyutu}
        />

        {/* ... İstatistik özeti ... */}

        {!searchQuery.trim() && gununKelimesi && (
          <GununKelimesiKarti 
             gununKelimesi={gununKelimesi} 
             karanlikMod={karanlikMod}
             metinBoyutu={metinBoyutu}
             onClick={() => setSeciliKelimeGrubu({ /* formatlanmış data */ })}
          />
        )}

        <SearchBox 
           searchQuery={searchQuery}
           setSearchQuery={setSearchQuery}
           mod={mod} setMod={setMod}
           hedefDil={hedefDil} setHedefDil={setHedefDil}
           // diğer proplar...
        />

        <section aria-label="Arama Sonuçları" className="flex flex-col gap-4">
          {/* gosterilenGruplar.map ile KelimeKarti bileşenini çağırıyoruz */}
        </section>

        {seciliKelimeGrubu && (
          <SozlukEkrani 
             seciliKelime={seciliKelimeGrubu}
             kapat={() => setSeciliKelimeGrubu(null)}
             // diğer proplar...
          />
        )}
      </main>
    </div>
  );
}